import { contentHash, type DimensionDefinition, type ModelContent } from "@/lib/gdss/core";
import { EVALUATOR_VERSION, EXPRESSION_LANGUAGE_VERSION, UNIT_CONVERSION_CATALOG_VERSION_V2 } from "@/lib/gdss/expression";
import { dynamicBindingHash, type DynamicBindingContent, type DynamicBindingSnapshot, type SimulationInputManifest } from "@/lib/gdss/simulation";
import { CONSTRAINT_POLICY, DYNAMIC_SEMANTIC_VERSION, GDSS_SIM_LIMITS_V1, SOLVER_VERSION } from "@/lib/gdss/simulation";

const provenance=[{kind:"HUMAN_PROPOSED" as const,description:"Neutral analytical simulation fixture",asserted_by:"test",metadata:{}}];
const unit=(key:string,symbol:string,dimension:DimensionDefinition)=>({key,revision:1,symbol,name:key,dimension,scale:1,offset:0,canonical_unit:key});
const variable=(symbol:string,unit_ref:string,dimension:DimensionDefinition)=>({kind:"Variable" as const,symbol,label:symbol,description:"",provenance,unit_ref,dimension,computational_role:"STATE" as const,epistemic_kind:"SIMULATED" as const});
const parameter=(symbol:string,unit_ref:string,dimension:DimensionDefinition,value:number)=>({kind:"Parameter" as const,symbol,label:symbol,description:"",provenance,unit_ref,dimension,default_value:value,valid_range:[-1e9,1e9] as [number,number]});
const formula=(symbol:string,expression_source:string,input_refs:string[],output_ref:string)=>({kind:"Formula" as const,symbol,label:symbol,description:"",provenance,expression_source,input_refs,output_ref,validity_domain:{}});
const ids={projectId:"00000000-0000-4000-8000-000000000031",modelVersionId:"00000000-0000-4000-8000-000000000032",bindingId:"00000000-0000-4000-8000-000000000033",bindingVersionId:"00000000-0000-4000-8000-000000000034"};

export function reservoirFixture(step=1,stepCount=10){
  const volume:DimensionDefinition=[3,0,0,0,0,0,0], flow:DimensionDefinition=[3,0,-1,0,0,0,0];
  const model:ModelContent={description:"Analytical reservoir",validity_domain:{},provenance,units:[unit("cubic_meter","m3",volume),unit("cubic_meter_per_second","m3/s",flow)],children:[variable("volume","cubic_meter",volume),parameter("qin","cubic_meter_per_second",flow,3),parameter("qout","cubic_meter_per_second",flow,1),variable("net_flow","cubic_meter_per_second",flow),formula("net_rate_formula","qin - qout",["qin","qout"],"net_flow")]};
  return build(model,{states:[{role:"STATE",stateRef:"volume",unit:{key:"cubic_meter",revision:1},dimension:volume,constraintRefs:[]}],rates:[{role:"RATE",rateRef:"volume_rate",stateRef:"volume",formulaRef:"net_rate_formula",outputRef:"net_flow",unit:{key:"cubic_meter_per_second",revision:1},dimension:flow}],algebraics:[],parameters:[{role:"PARAMETER",parameterRef:"qin"},{role:"PARAMETER",parameterRef:"qout"}],constraintRefs:[]},[{ref:"volume",value:10,unit:{key:"cubic_meter",revision:1},provenanceIdentity:"initial:test"}],[{ref:"qin",value:3,unit:{key:"cubic_meter_per_second",revision:1},provenanceIdentity:"parameter:qin"},{ref:"qout",value:1,unit:{key:"cubic_meter_per_second",revision:1},provenanceIdentity:"parameter:qout"}],step,stepCount);
}
export function thermalFixture(step=1,stepCount=Math.round(10/step)){
  const temperature:DimensionDefinition=[0,0,0,1,0,0,0], inverseTime:DimensionDefinition=[0,0,-1,0,0,0,0], rate:DimensionDefinition=[0,0,-1,1,0,0,0];
  const model:ModelContent={description:"Analytical thermal decay",validity_domain:{},provenance,units:[unit("kelvin","K",temperature),unit("inverse_second","1/s",inverseTime),unit("kelvin_per_second","K/s",rate)],children:[variable("temperature","kelvin",temperature),parameter("ambient","kelvin",temperature,20),parameter("k","inverse_second",inverseTime,0.1),variable("temperature_rate","kelvin_per_second",rate),formula("thermal_rate_formula","-k * (temperature - ambient)",["k","temperature","ambient"],"temperature_rate")]};
  return build(model,{states:[{role:"STATE",stateRef:"temperature",unit:{key:"kelvin",revision:1},dimension:temperature,constraintRefs:[]}],rates:[{role:"RATE",rateRef:"thermal_rate",stateRef:"temperature",formulaRef:"thermal_rate_formula",outputRef:"temperature_rate",unit:{key:"kelvin_per_second",revision:1},dimension:rate}],algebraics:[],parameters:[{role:"PARAMETER",parameterRef:"ambient"},{role:"PARAMETER",parameterRef:"k"}],constraintRefs:[]},[{ref:"temperature",value:100,unit:{key:"kelvin",revision:1},quantitySemantics:"ABSOLUTE",provenanceIdentity:"observed:test"}],[{ref:"ambient",value:20,unit:{key:"kelvin",revision:1},quantitySemantics:"ABSOLUTE",provenanceIdentity:"parameter:ambient"},{ref:"k",value:0.1,unit:{key:"inverse_second",revision:1},provenanceIdentity:"parameter:k"}],step,stepCount);
}

function build(model:ModelContent,parts:Pick<DynamicBindingContent,"states"|"rates"|"algebraics"|"parameters"|"constraintRefs">,initialConditions:SimulationInputManifest["initialConditions"],parameterValues:SimulationInputManifest["parameterValues"],step:number,stepCount:number){
  const modelContentHash=contentHash(model);
  const content:DynamicBindingContent={projectId:ids.projectId,modelVersionId:ids.modelVersionId,modelContentHash,dynamicSemanticVersion:DYNAMIC_SEMANTIC_VERSION,...parts,provenanceIdentities:["fixture:test"]};
  const binding:DynamicBindingSnapshot={...content,bindingId:ids.bindingId,bindingVersionId:ids.bindingVersionId,bindingVersion:1,dynamicBindingHash:dynamicBindingHash(content),lifecycleStatus:"PUBLISHED",model};
  const manifest:SimulationInputManifest={projectId:ids.projectId,modelVersionId:ids.modelVersionId,modelContentHash,bindingId:ids.bindingId,bindingVersionId:ids.bindingVersionId,bindingVersion:1,dynamicBindingHash:binding.dynamicBindingHash,dynamicSemanticVersion:DYNAMIC_SEMANTIC_VERSION,solverVersion:SOLVER_VERSION,initialConditions,parameterValues,temporalConfiguration:{start:0,step,stepCount,timeUnit:{key:"second",revision:1},unitConversionCatalogVersion:UNIT_CONVERSION_CATALOG_VERSION_V2},expressionLanguageVersion:EXPRESSION_LANGUAGE_VERSION,evaluatorVersion:EVALUATOR_VERSION,unitConversionCatalogVersion:UNIT_CONVERSION_CATALOG_VERSION_V2,resourceProfile:GDSS_SIM_LIMITS_V1,constraintPolicy:CONSTRAINT_POLICY};
  return {model,content,binding,manifest};
}
